package seed

import (
	"github.com/xdanny/hyperplane-workflows/internal/sdkworkflow"
	"github.com/xdanny/hyperplane-workflows/internal/store"
)

// ML is an editable recipe for the same general SDK agent. Only prediction
// arithmetic and evidence binding use an attached deterministic check.
func mlEngineeringTemplate() store.WorkflowTemplate {
	return sdkNodeTemplate("ml-engineering",
		"Plan a simple predictive baseline, approve the evaluation before training, compare it with naive predictors, and receive a reviewed model card. A trusted extra check recomputes the primary metric from submitted predictions; it does not prove training never accessed the evaluation data.",
		`Build and evaluate a simple predictive baseline for the declared decision.
Task: {slot:task}
Prediction target and when the answer becomes known: {slot:predictionTarget}
Available data and declared evaluation identities: {slot:dataDescription}
Train/evaluation split policy: {slot:splitPolicy}
Success metrics, first row primary: {slot:successMetric}
Constraints: {slot:constraints}
Runtime budget: {slot:runtimeBudget}
Environment: {slot:environment}
Handover: {slot:handover}
Preserve these owner declarations throughout. Missing optional values mean unspecified. Use actual available sources; do not substitute fixtures or invent results. Descriptions do not grant network access, source access or package installation: configure explicit permissions separately. Respect the application deadline and any tighter declared budget. Do not modify source data, deploy, publish or send the handover. A source hash identifies bytes; it does not prove that training could not read them. State any unproven training/holdout access boundary.`,
		[]store.ContextSlot{
			{ID: "task", Label: "Task", Required: true, Hint: "The decision this prediction supports, who acts on it and when.", Example: "Rank subscription accounts for the retention team's weekly calls"},
			{ID: "predictionTarget", Label: "Prediction target", Required: true, Hint: "What is predicted and when the true answer becomes known. Features must be available at prediction time.", Example: "Cancellation within 30 days of scoring; the true label becomes known after that window closes"},
			{ID: "dataDescription", Label: "Data available", Required: true, Hint: "Actual files or tables, source locations, row counts, dates, features, labels and gaps. Include declared evaluation-set identities, content hashes and custody limits where known; naming a source does not grant access.", Example: "/absolute/data/accounts.csv: one row per account per month, 18 months, features measured at scoring time; cancellation labels mature after 30 days; evaluation snapshot and access policy supplied by the owner"},
			{ID: "splitPolicy", Label: "How training and evaluation are separated", Required: true, Hint: "State the time cut, entity grouping or random split and why it fits the data. Fix this policy before seeing results.", Example: "Train on months 1–17; evaluate on month 18; no account appears on both sides, to avoid scoring memorisation"},
			{ID: "successMetric", Label: "Success metric and threshold", Required: true, Type: store.SlotTypeTable,
				Hint: "The first row is primary and is independently recomputed. Supported primary metrics are AUROC, PR-AUC (average precision), F1 and accuracy for binary labels 0 and 1. State the threshold with its comparison direction before training.",
				Columns: []store.SlotColumn{
					{ID: "metric", Label: "Metric", Required: true, Hint: "Primary: AUROC, PR-AUC (average precision), F1 or accuracy for labels 0 and 1. Other metrics may be secondary and must be reviewed separately."},
					{ID: "threshold", Label: "Threshold", Required: true, Hint: "Include the comparison direction, such as >= 0.65 or > 0.65; equality differs between these rules."},
					{ID: "operatingPoint", Label: "Operating point", Hint: "The decision rule. F1 and accuracy require a threshold, top count or top percentage, such as threshold 0.5 or top 2%."},
					{ID: "uncertaintyMethod", Label: "Uncertainty", Hint: "How uncertainty is estimated, such as bootstrap resampling. Blank means none was declared."},
					{ID: "worstSliceFloor", Label: "Worst-slice floor", Hint: "The minimum performance and grouping column, such as 0.45 on region. Blank means none was declared."},
				}, Example: `[{"metric":"PR-AUC","threshold":">= 0.65","operatingPoint":"top 2% of accounts","uncertaintyMethod":"bootstrap, 1000 resamples","worstSliceFloor":"0.45 on region"}]`},
			{ID: "constraints", Label: "Constraints", Hint: "Optional latency, artifact size, privacy, residency and cost limits. Do not infer permission from these notes.", Example: "No raw personal identifiers in delivered artifacts; nightly batch scoring inside the analytics environment"},
			{ID: "runtimeBudget", Label: "Runtime budget", Hint: "Optional wall-clock limit for training and evaluation. An overrun must be reported, without silently dropping comparisons or checks.", Example: "Training and evaluation within 20 minutes on the available CPU"},
			{ID: "environment", Label: "Where it runs", Hint: "Optional interpreter, installed tools and intended operating environment. Network access and tool setup require separate permission settings.", Example: "Python 3 with available local libraries; no package installation or network access"},
			handoverSlot("model card", "a one-page Markdown model card for #ml-review"),
		},
		sdkworkflow.Node{ID: "plan", Kind: "task", Title: "Inspect the data and plan the baseline", Instruction: `Inspect available source schemas and development data without training or tuning a model. Respect declared holdout custody; if access cannot be separated, disclose that limitation and do not claim isolation. Write plan.md with the business decision, prediction-time feature availability, label maturity, source identities and gaps, declared split and its implementation, train-only preprocessing, the simplest feasible model and meaningful naive predictors. Fix primary and secondary metrics, thresholds, operating point, uncertainty method, slice floors and comparison population before results exist. Plan at least three concrete leakage checks and a copied-data negative control that they must detect. Explain resource/privacy constraints and feasibility. Missing data or impossible policies must be resolved before training; do not invent a substitute or silently change the split.`},
		sdkworkflow.Node{ID: "plan-review", Kind: "check", Title: "Review the data and evaluation plan", Instruction: `Independently inspect plan/plan.md and source evidence against the owner declarations. Reject unavailable or substituted data, post-outcome features, an incompatible split, preprocessing that can see evaluation rows, changed success criteria or an unfairly weak comparison. Require executable naive predictors on the same evaluation population, declared uncertainty and slice tests, and leakage checks with a concrete negative control. Require an explicit account of holdout access limitations; a hash is not custody proof. Review feasibility within stated resource and privacy limits. Do not invent optional requirements or authorize access.`},
		sdkworkflow.Node{ID: "approve-plan", Kind: "approval", Title: "Approve the baseline and evaluation plan", Instruction: `Review plan/plan.md and the independent review. Confirm source identities, label availability, split policy, baseline comparisons, metrics and thresholds, controls, resource/privacy limits and any disclosed custody limitation before training. A changed plan needs a new review and approval; approval does not grant filesystem, network or deployment permissions.`},
		sdkworkflow.Node{ID: "baseline", Kind: "task", Title: "Build and evaluate the approved baseline", Acceptance: "prediction-metrics", Inputs: map[string]string{"successMetric": "{slot:successMetric}", "dataDescription": "{slot:dataDescription}"}, Instruction: `Implement the approved plan using actual available data. Preserve source files and the declared split. Fit preprocessing on training rows only; do not tune features, thresholds or model selection on evaluation results. Run the model and every agreed naive predictor on the same evaluation rows, recording counts, spans, seeds, metric deltas, uncertainty and per-slice results where declared. Execute the leakage checks and copied-data negative control with concrete evidence, not assertions. Produce runnable code, predictions.csv, eval-report.json and checks.sh following the attached extra-check requirements; finish all edits and then run exactly sh checks.sh inside the SDK sandbox. The trusted checker writes score-report.json after acceptance; do not create it yourself. Keep missing evidence and constraint failures explicit. Do not reduce the population, omit comparisons or relax thresholds to obtain a pass.`},
		sdkworkflow.Node{ID: "evaluation-review", Kind: "check", Title: "Review execution and evaluation evidence", Instruction: `Independently inspect the actual code, evaluation report, predictions and trusted score report in baseline/. Confirm agreement with the approved plan and declared primary metric, threshold and operating point. Inspect the executed split, label availability and train-only preprocessing; verify naive predictors used the same rows and report every delta. Review at least three evidenced leakage checks and the same check programs detecting the injected bad case. Check declared uncertainty, worst slices and resource/privacy limits. Reject fabricated data, hardcoded scores, holdout tuning, missing execution or unmet owner requirements. Recomputed arithmetic validates submitted rows, not their label provenance, completeness or training independence. State the weakest assumption and any unproven custody boundary; model review remains fallible.`},
		sdkworkflow.Node{ID: "model-card", Kind: "document", Title: "Write the model card", Instruction: `Write a standalone model card based on the reviewed evidence. Lead with the outcome and recommended next action: retain as a baseline, iterate or stop. State intended and out-of-scope use, data identity and coverage, label availability, declared versus actual split, model/preprocessing, primary and secondary results with thresholds, naive comparisons, uncertainty, worst slices and leakage controls. Include measured constraint compliance, reproducible code/file references and the review's weakest assumption. Preserve failed, missing or unproven evidence, especially holdout custody; local training is not deployment readiness. Define jargon and give every quantity its unit and denominator. Prepare the declared handover format and recipient reference without sending anything; invent neither if unspecified.`},
		sdkworkflow.Node{ID: "card-review", Kind: "check", Title: "Review the model card and limitations", Instruction: `Compare model-card.md with the actual code, reports and independent evaluation review. Require intended and out-of-scope use, data/split context, each declared metric with its threshold and uncertainty, naive comparisons, worst slices, executed controls, measured constraints and reproduction instructions. Reject unsupported correctness, unseen-data or production-readiness claims. Preserve the weakest assumption and every material caveat at full strength. The opening must explain the outcome and next action; quantities need units and denominators and jargon needs definitions. Give a one-sentence restatement of the task, result and recommended next action.`},
	)
}
